/* global Office */
import React, { useEffect, useState, useRef } from "react";
import { createRoot } from "react-dom/client";
import {
  FluentProvider,
  webLightTheme,
  Title3,
  Body1,
  Button,
  Spinner,
  Badge,
} from "@fluentui/react-components";
import {
  Dismiss24Regular,
  DocumentPdf24Regular,
  Print24Regular,
  ArrowDownload24Regular,
} from "@fluentui/react-icons";
import { getStoredPdfForPreview } from "../services/pdfStorage";

export const PreviewDialog: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [pdfUrl, setPdfUrl] = useState<string | null>(null);
  const [pdfSize, setPdfSize] = useState<number>(0);
  const [error, setError] = useState<string | null>(null);
  const iframeRef = useRef<HTMLIFrameElement>(null);

  useEffect(() => {
    let activeUrl: string | null = null;

    const loadPdf = async () => {
      try {
        setLoading(true);
        const data = await getStoredPdfForPreview();
        if (!data || data.byteLength === 0) {
          setError("Tidak ada data PDF yang ditemukan untuk ditampilkan.");
          setLoading(false);
          return;
        }

        setPdfSize(data.byteLength);
        const blob = new Blob([data as unknown as BlobPart], { type: "application/pdf" });
        activeUrl = URL.createObjectURL(blob);
        setPdfUrl(activeUrl);
        setLoading(false);

        // Jika mode auto-print aktif
        const autoPrint = sessionStorage.getItem("eps_auto_print") === "true";
        if (autoPrint) {
          sessionStorage.removeItem("eps_auto_print");
          // Beri waktu iframe merender, lalu fokuskan
          setTimeout(() => {
            try {
              iframeRef.current?.contentWindow?.focus();
            } catch {
              // Abaikan jika cross-origin security membatasi
            }
          }, 600);
        }
      } catch (err) {
        setError(err instanceof Error ? err.message : String(err));
        setLoading(false);
      }
    };

    if (typeof Office !== "undefined" && Office.onReady) {
      Office.onReady(() => {
        loadPdf();
      });
    } else {
      loadPdf();
    }

    // Fallback jika Office.onReady membutuhkan waktu lama
    const fallbackTimer = setTimeout(() => {
      if (!activeUrl && loading) {
        loadPdf();
      }
    }, 1000);

    return () => {
      clearTimeout(fallbackTimer);
      if (activeUrl) {
        URL.revokeObjectURL(activeUrl);
      }
    };
  }, []);

  const handleClose = () => {
    try {
      if (typeof Office !== "undefined" && Office.context?.ui?.messageParent) {
        Office.context.ui.messageParent(JSON.stringify({ action: "CLOSE_DIALOG" }));
        return;
      }
    } catch {
      // Fallback
    }
    window.close();
  };

  const handlePrint = () => {
    if (iframeRef.current?.contentWindow) {
      try {
        iframeRef.current.contentWindow.focus();
        iframeRef.current.contentWindow.print();
        return;
      } catch {
        // Fallback
      }
    }
    window.print();
  };

  const handleDownload = () => {
    if (!pdfUrl) return;
    const a = document.createElement("a");
    a.href = pdfUrl;
    a.download = "excel-print-studio.pdf";
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  const formatSize = (bytes: number) => {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(2)} MB`;
  };

  return (
    <FluentProvider
      theme={webLightTheme}
      style={{
        height: "100vh",
        display: "flex",
        flexDirection: "column",
        background: "#f3f4f6",
        boxSizing: "border-box",
      }}
    >
      {/* Header bar */}
      <header
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          padding: "10px 16px",
          background: "#ffffff",
          borderBottom: "1px solid #e5e7eb",
          boxShadow: "0 1px 3px rgba(0,0,0,0.05)",
          flexShrink: 0,
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: "10px" }}>
          <DocumentPdf24Regular style={{ color: "#d13438", fontSize: "24px" }} />
          <div>
            <Title3 style={{ fontSize: "16px", margin: 0, fontWeight: 600 }}>Pratinjau PDF Penuh</Title3>
          </div>
          {pdfSize > 0 && (
            <Badge appearance="tint" color="informative">
              {formatSize(pdfSize)}
            </Badge>
          )}
        </div>

        <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
          <Button
            appearance="primary"
            icon={<Print24Regular />}
            onClick={handlePrint}
            disabled={!pdfUrl}
          >
            Cetak (Ctrl+P)
          </Button>

          <Button
            appearance="secondary"
            icon={<ArrowDownload24Regular />}
            onClick={handleDownload}
            disabled={!pdfUrl}
          >
            Unduh
          </Button>

          <Button
            appearance="subtle"
            icon={<Dismiss24Regular />}
            onClick={handleClose}
            aria-label="Tutup pratinjau"
          />
        </div>
      </header>

      {/* Main Viewport */}
      <main
        style={{
          flex: 1,
          position: "relative",
          width: "100%",
          height: "calc(100vh - 58px)",
          background: "#525659",
        }}
      >
        {loading && (
          <div
            style={{
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              height: "100%",
              color: "#ffffff",
            }}
          >
            <Spinner label="Memuat dokumen PDF untuk pratinjau..." />
          </div>
        )}

        {error && (
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              justifyContent: "center",
              alignItems: "center",
              height: "100%",
              padding: 24,
              textAlign: "center",
              color: "#ffffff",
            }}
          >
            <Body1 style={{ color: "#ff8b8b", marginBottom: 16 }}>{error}</Body1>
            <Button appearance="secondary" onClick={handleClose}>
              Tutup
            </Button>
          </div>
        )}

        {pdfUrl && !loading && (
          <iframe
            ref={iframeRef}
            src={pdfUrl}
            title="Pratinjau Dokumen PDF Penuh"
            style={{
              width: "100%",
              height: "100%",
              border: "none",
              display: "block",
            }}
          />
        )}
      </main>
    </FluentProvider>
  );
};

// Mount component ke DOM di dialog.html
const container = document.getElementById("dialog-root");
if (container) {
  const root = createRoot(container);
  root.render(<PreviewDialog />);
}
